/// Number of reserved hugepages.
///
/// Hugepages for which a commitment to allocate has been made, but no allocation has yet been
/// made.
/// This is reported as a separate metric rather than a `usage` state because reserved pages are
/// already counted in `free` pages.
/// They represent a subset of free pages that cannot be used for non-reserved allocations.
///
/// Stability: development.
#[cfg(feature = "experimental")]
pub const SYSTEM_MEMORY_LINUX_HUGEPAGES_RESERVED: Metric = Metric {
    name: "system.memory.linux.hugepages.reserved",
    instrument: Instrument::UpDownCounter,
    unit: "{page}",
    brief: r#"Number of reserved hugepages."#,
};

/// Number of surplus hugepages.
///
/// Overcommitted hugepages beyond the persistent pool.
/// This is reported as a separate metric rather than a `usage` state because surplus pages can
/// be in either `used` or `free` state.
/// Including them in `usage` would break the convention that `usage` states sum to the `limit`.
///
/// Stability: development.
#[cfg(feature = "experimental")]
pub const SYSTEM_MEMORY_LINUX_HUGEPAGES_SURPLUS: Metric = Metric {
    name: "system.memory.linux.hugepages.surplus",
    instrument: Instrument::UpDownCounter,
    unit: "{page}",
    brief: r#"Number of surplus hugepages."#,
};

